(function() { 'use strict'; const AppConfig = { version: '2.0.0', name: 'Go 语言学习教程', debug: false }; function initApp() { console.log(`[App] ${AppConfig.name} v${AppConfig.version} 启动`); if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', onDOMReady); } else { onDOMReady(); } } function onDOMReady() { console.log('[App] DOM 加载完成'); initModules(); bindGlobalEvents(); window.appInitialized = true; console.log('[App] 应用初始化完成'); } function initModules() { if (typeof Navigation !== 'undefined') { Navigation.init(); } if (typeof CodeBlocks !== 'undefined') { CodeBlocks.init(); } if (typeof Theme !== 'undefined') { Theme.init(); } } function bindGlobalEvents() { document.addEventListener('visibilitychange', function() { if (document.hidden) { console.log('[App] 页面隐藏'); } else { console.log('[App] 页面显示'); } }); window.addEventListener('resize', Utils.debounce(function() { console.log('[App] 窗口大小变化'); }, 250)); window.addEventListener('scroll', Utils.throttle(function() { }, 100)); document.addEventListener('keydown', function(e) { if (e.altKey && e.key === 'h') { e.preventDefault(); window.location.href = 'index.html'; } }); } function getAppInfo() { return { name: AppConfig.name, version: AppConfig.version, modules: { navigation: typeof Navigation !== 'undefined', codeBlocks: typeof CodeBlocks !== 'undefined', theme: typeof Theme !== 'undefined', utils: typeof Utils !== 'undefined' } }; } initApp(); window.GoTutorial = { version: AppConfig.version, getAppInfo, config: AppConfig }; })();